 function localAnswer(q){const t=q.toLowerCase();if(/(who are you|what are you|what can you do|capabilities)/.test(t))return '<h2>I’m gemini.AI.upgreaded</h2><p>I’m a browser-based assistant that can explain ideas, translate, write and review code, summarize text, plan projects, solve structured problems, and help with game design.</p><ul><li>With an API key, I can use live Gemini models.</li><li>Without a key, I provide reliable built-in guidance.</li><li>I support attached text-based files for local context.</li></ul>';if(/(time|date|today|clock)/.test(t)){try{return '<h2>Current time</h2><p>'+esc(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Istanbul',dateStyle:'full',timeStyle:'medium'}).format(new Date()))+' — Europe/Istanbul (UTC+3).</p>'}catch(e){return '<p>Time is available in the footer.</p>'}}if(/translate|translation|çev|tercüme/.test(t)){const m=q.match(/(.+?)\s+(?:to|into|→|ile)\s+(.+)/i);return '<h2>Translation request</h2><p>Add the exact phrase and target language, for example: <b>“Translate ‘good morning’ into Turkish.”</b></p>'}if(/hello|hi\b|merhaba|selam/.test(t))return '<h2>Hello</h2><p>What would you like to work on? I can begin with a plan, explanation, comparison, or implementation.</p>';if(/(invent|discover|invention|kim icat|icat eden)/.test(t))return '<h2>A useful way to answer invention questions</h2><p>Major inventions often have several contributors, predecessor devices, and independent invention claims. The precise answer depends on the inventor, date, country, and type of invention you mean.</p><p>Please name the invention or add a date/context, and I’ll distinguish established facts from disputed or competing claims.</p>';if(/(code|javascript|python|html|css|bug|debug)/.test(t))return '<h2>Code support</h2><p>Share the language, what you are trying to achieve, the relevant code, and the exact error or expected behavior. I’ll:</p><ol><li>Identify the likely cause.</li><li>Explain the fix clearly.</li><li>Provide a minimal, testable solution.</li></ol>';if(/(plan|project|roadmap)/.test(t))return '<h2>A focused project plan</h2><ol><li><b>Define the outcome:</b> one sentence describing what “done” looks like.</li><li><b>Choose constraints:</b> timeline, audience, budget, and technology.</li><li><b>Break the work:</b> core experience, supporting features, and verification.</li><li><b>Set milestones:</b> build, test, review, and ship.</li></ol><p>Tell me the project idea and constraints for a tailored plan.</p>';return '<h2>Let’s make this specific</h2><p>I can help you analyze, compare, create, translate, or solve this. Share the key details, desired format, and constraints; for a quick answer, use this structure:</p><ul><li><b>Goal:</b> what outcome you want</li><li><b>Context:</b> relevant facts or files</li><li><b>Format:</b> table, steps, code, or summary</li></ul>'}
