 async function callGemini(q){const key=$('apiKey').value.trim();if(!key)return null;const selected=$('modelSelect').value;const base='https://generativelanguage.googleapis.com';let models=[];try{models=await discoverModels(base,key,abort.signal)}catch(e){models=[]}if(selected!==''&&selected!=='auto')models.unshift(selected);if(!models.length)models=['gemini-2.5-flash','gemini-2.5-pro','gemini-3-flash-preview','gemini-2.0-flash'];models=[...new Set(models)];for(let i=0;i<models.length;i++){const model=models[i];for(let attempt=0;attempt<2;attempt++){try{const controller=new AbortController();const timer=setTimeout(()=>{try{controller.abort()}catch(e){}},35000);abort.signal.addEventListener('abort',()=>{try{controller.abort()}catch(e){}},{once:true});const context=attachedText? '\n\nAttached document context:\n'+attachedText.slice(0,12000):'';const system='You are gemini.AI.upgreaded, a precise, direct, helpful assistant. Answer first, then structure with concise headings, bullets or tables. Tone: '+$('toneSelect').value+'. Be honest and never invent sources.';const body={system_instruction:{parts:[{text:system}]},contents:[{role:'user',parts:[{text:q+context}]}],generationConfig:{temperature:mode==='Creative'?0.9:0.5,maxOutputTokens:2048}};const r=await fetch(base+'/v1beta/models/'+encodeURIComponent(model)+':generateContent?key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:controller.signal});clearTimeout(timer);if(r.ok){const j=await r.json();const text=j?.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('')||'';if(text)return text}const status=r.status;if(status===404||status===429||status===503){await new Promise(r=>setTimeout(r,attempt?900:350));continue}if(status===400){return null}return null}catch(e){if(abort&&abort.aborted)throw e;await new Promise(r=>setTimeout(r,300));}}}return null}
 async function send(){if(busy)return;try{const input=$('input');const q=input.value.trim();if(!q&&!attachedText)return;busy=true;$('sendBtn').disabled=true;abort=new AbortController();addMsg('user',q||('Review attached file: '+attachedName));input.value='';autoGrow();const typing=document.createElement('div');typing.className='message ai';typing.innerHTML='<div class="ai-mark"></div><div class="answer"><span class="typing"><i></i><i></i><i></i></span></div>'; $('chatInner').appendChild(typing);$('chat').scrollTop=$('chat').scrollHeight;let answer='';try{answer=await callGemini(q||'Summarize and explain this attached context')}catch(e){answer=''}typing.remove();if(!answer)answer=localAnswer(q||'attached file');addMsg('ai',md(answer));chatHistory.push({q,a:answer});try{store.set('geminiHistory',JSON.stringify(chatHistory.slice(-20)))}catch(e){}}catch(e){try{const inner=$('chatInner');if(inner)inner.querySelectorAll('.typing').forEach(t=>t.parentElement?.parentElement?.remove())}catch(z){}}finally{busy=false;$('sendBtn').disabled=false;abort=null}}
